use umineko_codec_deflate::{Deflate, DeflateBlock, DeflateCodes, DeflateError, DeflateRun};

fn text(length: usize) -> Vec<u8> {
    let words = ["alpha ", "beta ", "gamma ", "delta ", "alpha ", "beta "];
    let mut data = Vec::new();
    while data.len() < length {
        data.extend_from_slice(words[data.len() % words.len()].as_bytes());
    }
    data.truncate(length);
    data
}

fn noise(length: usize) -> Vec<u8> {
    (0..length).map(|index| ((index * index / 7 + index * 37) % 251) as u8).collect()
}

