fn cases() -> Vec<(&'static str, Vec<u8>, &'static [u8], &'static [u8])> {
    [
        ("empty", Vec::new(), EMPTY.as_slice(), EMPTY_STORED.as_slice()),
        ("byte", b"a".to_vec(), BYTE.as_slice(), BYTE_STORED.as_slice()),
        ("short", b"hello world".to_vec(), SHORT.as_slice(), SHORT_STORED.as_slice()),
        ("runs", vec![b'a'; 5000], RUNS.as_slice(), RUNS_STORED.as_slice()),
        ("text", text(20000), TEXT.as_slice(), TEXT_STORED.as_slice()),
        ("noise", noise(4000), NOISE.as_slice(), NOISE_STORED.as_slice()),
    ]
    .to_vec()
}

#[test]
fn inflates_streams_zlib_deflated() {
    let codec = Deflate::default();
    for (name, data, dynamic, stored) in cases() {
        assert_eq!(codec.decode(dynamic).unwrap(), data, "dynamic {name}");
        assert_eq!(codec.decode(stored).unwrap(), data, "stored {name}");
    }
}

#[test]
fn round_trips_every_shape() {
    let codec = Deflate::default();
    for (name, data, _, _) in cases() {
        let encoded = codec.compress(&data).unwrap();
        assert_eq!(codec.decompress(&encoded).unwrap(), data, "{name}");
    }
}

#[test]
fn repeats_shrink() {
    let codec = Deflate::default();
    let data = text(20000);
    let encoded = codec.encode(&data).unwrap();
    assert!(encoded.len() < data.len() / 10, "{} vs {}", encoded.len(), data.len());
}

#[test]
fn noise_never_grows_much() {
    let codec = Deflate::default();
    let data = noise(4000);
    let encoded = codec.encode(&data).unwrap();
    assert!(encoded.len() <= data.len() + 16, "{} vs {}", encoded.len(), data.len());
}

#[test]
fn a_level_of_zero_only_stores() {
    let codec = Deflate { level: 0, ..Deflate::default() };
    let data = text(1000);
    let encoded = codec.encode(&data).unwrap();
    assert_eq!(encoded, codec.store(&data));
    assert_eq!(codec.decode(&encoded).unwrap(), data);
}

#[test]
fn every_window_round_trips() {
    for window in [9, 10, 12, 15] {
        let codec = Deflate { window, ..Deflate::default() };
        let data = text(9000);
        let encoded = codec.encode(&data).unwrap();
        assert_eq!(Deflate::default().decode(&encoded).unwrap(), data, "window {window}");
    }
}

#[test]
fn a_broken_stream_is_refused() {
    let codec = Deflate::default();
    assert_eq!(codec.decode(&[]), Err(DeflateError::Truncated));
    assert_eq!(codec.decode(&[0x07]), Err(DeflateError::Format));
    assert_eq!(codec.decode(&[0x01, 0x05, 0x00, 0x00, 0x00]), Err(DeflateError::Format));
}

#[test]
fn a_limit_stops_a_bomb() {
    let bomb = Deflate::default().encode(&vec![0; 50000]).unwrap();
    let codec = Deflate { limit: Some(1000), ..Deflate::default() };
    assert_eq!(codec.decode(&bomb), Err(DeflateError::Limit));
}

#[test]
fn streaming_matches_the_one_shot_call() {
    let codec = Deflate::default();
    let data = text(5000);
    let mut encoder = codec.encoder();
    for chunk in data.chunks(211) {
        encoder.update(chunk).unwrap();
    }
    let encoded = encoder.finalize().unwrap();
    assert_eq!(encoded, codec.compress(&data).unwrap());
    let mut decoder = codec.decoder();
    decoder.update(&encoded).unwrap();
    assert_eq!(decoder.finalize().unwrap(), data);
}

#[test]
fn stored_blocks_round_trip() {
    let codec = Deflate::default();
    for (name, data, _, _) in cases() {
        let stored = codec.store(&data);
        assert_eq!(codec.decode(&stored).unwrap(), data, "{name}");
    }
    let long = text(200000);
    assert_eq!(codec.decode(&codec.store(&long)).unwrap(), long);
}

/// The code lengths a run of the code length alphabet expands back to.
fn expand(runs: &[DeflateRun]) -> Vec<u8> {
    let mut lengths: Vec<u8> = Vec::new();
    for run in runs {
        match run.symbol {
            16 => {
                let last = *lengths.last().unwrap();
                lengths.resize(lengths.len() + run.extra as usize + 3, last);
            }
            17 => lengths.resize(lengths.len() + run.extra as usize + 3, 0),
            18 => lengths.resize(lengths.len() + run.extra as usize + 11, 0),
            symbol => lengths.push(symbol as u8),
        }
    }
    lengths
}

#[test]
fn dynamic_blocks_round_trip() {
    let codec = Deflate::default();
    for (name, data, _, _) in cases() {
        let tokens = codec.tokens(&data);
        let block = codec.block(&data, &tokens, DeflateBlock::Dynamic).unwrap();
        assert_eq!(codec.decode(&block).unwrap(), data, "{name}");
    }
    for data in [text(200000), noise(70000), vec![0u8; 100], (0..=255u8).cycle().take(60000).collect::<Vec<u8>>()] {
        let tokens = codec.tokens(&data);
        let block = codec.block(&data, &tokens, DeflateBlock::Dynamic).unwrap();
        assert_eq!(codec.decode(&block).unwrap(), data, "length {}", data.len());
    }
}

#[test]
fn a_dynamic_block_opens_with_the_header_the_format_names() {
    let codec = Deflate::default();
    let data = text(20000);
    let block = codec.block(&data, &codec.tokens(&data), DeflateBlock::Dynamic).unwrap();
    assert_eq!(block[0] & 1, 1, "the block is the last one");
    assert_eq!((block[0] >> 1) & 3, DeflateBlock::Dynamic.bits() as u8);
    assert_eq!(DeflateBlock::from_bits(2), Ok(DeflateBlock::Dynamic));
    assert_eq!(DeflateBlock::from_bits(3), Err(DeflateError::Format));
}

#[test]
fn a_dynamic_header_stays_inside_the_counts_the_format_names() {
    let codec = Deflate::default();
    for (name, data, _, _) in cases() {
        let codes = DeflateCodes::from_tokens(&codec.tokens(&data)).unwrap();
        let (lengths, literals, offsets) = codes.lengths();
        assert!((257..=286).contains(&literals), "{name} names {literals} literal codes");
        assert!((1..=30).contains(&offsets), "{name} names {offsets} distance codes");
        assert_eq!(lengths.len(), literals + offsets, "{name}");
        assert!(lengths.iter().all(|length| *length <= 15), "{name} carries a code longer than the format allows");
    }
}

#[test]
fn code_length_runs_stay_inside_the_ranges_the_format_names() {
    let codec = Deflate::default();
    for (name, data, _, _) in cases() {
        let codes = DeflateCodes::from_tokens(&codec.tokens(&data)).unwrap();
        let (lengths, _, _) = codes.lengths();
        let runs = DeflateCodes::runs(&lengths);
        for run in runs.iter() {
            let bits = match run.symbol {
                0..=15 => 0,
                16 => 2,
                17 => 3,
                18 => 7,
                symbol => panic!("{name} writes code length symbol {symbol}"),
            };
            assert_eq!(run.bits, bits, "{name} writes symbol {} with {} extra bits", run.symbol, run.bits);
            assert!(run.extra < 1 << bits, "{name} writes {} into {bits} extra bits", run.extra);
        }
        assert_eq!(expand(&runs), lengths, "{name}");
    }
    let runs = DeflateCodes::runs(&[0; 300]);
    assert_eq!(expand(&runs), [0; 300]);
    let runs = DeflateCodes::runs(&[4; 200]);
    assert_eq!(expand(&runs), [4; 200]);
    for length in 0..200 {
        let lengths: Vec<u8> = (0..length).map(|index| (index % 3) as u8 * (index / 17) as u8 % 16).collect();
        assert_eq!(expand(&DeflateCodes::runs(&lengths)), lengths, "length {length}");
    }
}

#[test]
fn dynamic_blocks_beat_fixed_blocks_on_skewed_data() {
    let codec = Deflate::default();
    for (name, data) in [("runs", vec![b'a'; 5000]), ("text", text(20000)), ("noise", noise(4000))] {
        let tokens = codec.tokens(&data);
        let fixed = codec.block(&data, &tokens, DeflateBlock::Fixed).unwrap();
        let dynamic = codec.block(&data, &tokens, DeflateBlock::Dynamic).unwrap();
        assert!(dynamic.len() < fixed.len(), "{name}: dynamic {} fixed {}", dynamic.len(), fixed.len());
        assert!(codec.encode(&data).unwrap().len() <= dynamic.len(), "{name}");
    }
}

#[test]
fn every_block_kind_carries_the_same_content() {
    let codec = Deflate::default();
    for (name, data, _, _) in cases() {
        let tokens = codec.tokens(&data);
        for kind in [DeflateBlock::Stored, DeflateBlock::Fixed, DeflateBlock::Dynamic] {
            let block = codec.block(&data, &tokens, kind).unwrap();
            assert_eq!(codec.decode(&block).unwrap(), data, "{name} as {kind:?}");
        }
    }
}
